let stdlib_source_texts () = List.map snd (stdlib_sources ())

type compiled_stdlib = {
  state : Lg.Compiler.state;
  ocaml_source : string;
}

let compiled_stdlib_cache = ref []

let compiled_stdlib target =
  let target_name = Lg.Target.to_string target in
  match List.assoc_opt target_name !compiled_stdlib_cache with
  | Some cached -> cached
  | None ->
      let state, reversed_outputs =
        List.fold_left
          (fun (state, outputs) (source_filename, source_text) ->
            let state, output =
              match
                Lg.Compiler.compile_chunk_with_filename ~target
                  ~filename:source_filename state source_text
              with
              | Ok compiled -> compiled
              | Error (error : Lg.Compiler.compile_error) ->
                  let location =
                    match error.location with
                    | Some location ->
                        ":" ^ string_of_int location.loc_start.pos_lnum
                    | None -> ""
                  in
                  failwith
                    ("failed to compile " ^ source_filename ^ location ^ ": "
                   ^ error.message)
            in
            (state, output :: outputs))
          (Lg.Compiler.empty_state, []) (stdlib_sources ())
      in
      let cached =
        {
          state = Lg.Compiler.with_source_scope "" state;
          ocaml_source =
            reversed_outputs |> List.rev |> String.concat "\n";
        }
      in
      compiled_stdlib_cache :=
        (target_name, cached) :: !compiled_stdlib_cache;
      cached

let compile_with_stdlib target filename source =
  let stdlib = compiled_stdlib target in
  let _, output =
    Lg.Compiler.compile_chunk_with_filename ~target ~filename stdlib.state
      source
    |> expect_ok
  in
  output

let compile_with_stdlib_result target filename source =
  let stdlib = compiled_stdlib target in
  Lg.Compiler.compile_chunk_with_filename ~target ~filename stdlib.state source
  |> Result.map snd

let compile_string_with_stdlib ?(target = Lg.Target.default) source =
  let stdlib = compiled_stdlib target in
  Lg.Compiler.compile_chunk_with_filename ~target
    ~filename:"test/source_core_program.cljc" stdlib.state source
  |> Result.map snd

let compile_string_from_stdlib ?(target = Lg.Target.default) source =
  let stdlib = compiled_stdlib target in
  Lg.Compiler.compile_chunk_with_filename ~target
    ~filename:"test/source_core_program.cljc" stdlib.state source
  |> Result.map snd

let stdlib_state target = (compiled_stdlib target).state

module Raw_lg = Lg

module Lg = struct
  include Raw_lg

  module Compiler = struct
    include Raw_lg.Compiler

    let compile_string ?(target = Target.default) source =
      compile_string_from_stdlib ~target source

    let compile_parsetree ?(target = Target.default) source =
      let stdlib = compiled_stdlib target in
      Raw_lg.Compiler.compile_chunk_parsetree ~target stdlib.state source
      |> Result.map snd

    let compile_parsetree_with_filename ?(target = Target.default) ~filename
        source =
      let stdlib = compiled_stdlib target in
      Raw_lg.Compiler.compile_chunk_parsetree_with_filename ~target ~filename
        stdlib.state source
      |> Result.map snd
  end

  module Toolchain = struct
    include Raw_lg.Toolchain

    let analyze ?(target = Target.default) ?(filename = "<string>") source =
      let stdlib = compiled_stdlib target in
      Raw_lg.Toolchain.analyze_from_state ~target ~filename stdlib.state source
  end

  module Language_service = struct
    include Raw_lg.Language_service

    let analyze ~filename source =
      let stdlib = compiled_stdlib Target.Native in
      Raw_lg.Language_service.analyze_from_state ~filename stdlib.state source

    let analyze_workspace sources =
      let stdlib = compiled_stdlib Target.Native in
      Raw_lg.Language_service.analyze_workspace_from_state stdlib.state sources
  end
end

let compile_chunks_with_stdlib target sources =
  let stdlib = compiled_stdlib target in
  let _, reversed_outputs =
    List.fold_left
      (fun (state, outputs) (source_filename, source_text) ->
        let state, output =
          Lg.Compiler.compile_chunk_with_filename ~target
            ~filename:source_filename state source_text
          |> expect_ok
        in
        (state, output :: outputs))
      (stdlib.state, [ stdlib.ocaml_source ]) sources
  in
  reversed_outputs |> List.rev |> String.concat "\n"

let test_compiler_tests_reuse_precompiled_stdlib_state () =
  let first = compiled_stdlib Lg.Target.Native in
  let second = compiled_stdlib Lg.Target.Native in
  if first != second then
    failwith "compiler tests must reuse one precompiled stdlib state per target";
  Lg.Compiler.compile_string {|(str "source-core")|} |> expect_ok |> ignore;
  Raw_lg.Compiler.compile_string {|(str "raw-core")|}
  |> expect_error "unknown function str"

let rec files_with_suffix suffix directory =
  Sys.readdir directory |> Array.to_list
  |> List.concat_map (fun name ->
         let path = Filename.concat directory name in
         if Sys.is_directory path then files_with_suffix suffix path
         else if Filename.check_suffix path suffix then [ path ]
         else [])

let test_lg_signature_sidecars_use_lgi_extension () =
  let roots =
    [ "stdlib"; "datascript"; "test/datascript" ]
    |> List.map (Filename.concat (repo_root ()))
  in
  let legacy = List.concat_map (files_with_suffix ".mil") roots in
  if legacy <> [] then
    failwith
      ("LG signature sidecars must use .lgi, found legacy .mil files: "
      ^ String.concat ", " legacy);
  let lg_syntax_mli =
    roots
    |> List.concat_map (files_with_suffix ".mli")
    |> List.filter (fun path ->
           let source = read_file path |> String.trim in
           [ "(ns "; "(signature "; "(type "; "(type-record ";
             "(type-variant " ]
           |> List.exists (fun prefix ->
                  String.starts_with ~prefix source))
  in
  if lg_syntax_mli <> [] then
    failwith
      (".mli files must use OCaml syntax; move LG signature forms to .lgi: "
      ^ String.concat ", " lg_syntax_mli);
  if
    not
      (Sys.file_exists
         (Filename.concat (repo_root ()) "stdlib/clojure/core.lgi"))
  then failwith "missing stdlib/clojure/core.lgi LG signature sidecar";
  [ "test/dune"; "test/datascript_conn_tests.inc"; "test/compiler_tests.ml" ]
  |> List.iter (fun manifest ->
         let source = read_file (Filename.concat (repo_root ()) manifest) in
         let implementation_count =
           count_substring source "datascript/upstream/util.cljc"
         in
         let interface_count =
           count_substring source "datascript/lg/util.lgi"
         in
         if implementation_count <> interface_count then
           failwith
             (Printf.sprintf
                "datascript.util interface/source count mismatch in %s: %d/%d"
                manifest interface_count implementation_count))

let rec source_files_under directory =
  Sys.readdir directory |> Array.to_list
  |> List.concat_map (fun name ->
         let path = Filename.concat directory name in
         if Sys.is_directory path then source_files_under path
         else if Filename.check_suffix path ".ml" then [ path ]
         else [])

let wrapped_module index source =
  Printf.sprintf "module Case_%04d = struct\n%s\nend\n" index source

let native_stdlib_prelude () = (compiled_stdlib Lg.Target.Native).ocaml_source

let strip_native_stdlib_prelude source =
  let prelude = native_stdlib_prelude () in
  if String.starts_with ~prefix:prelude source then
    let offset = String.length prelude in
    let offset =
      if offset < String.length source && source.[offset] = '\n' then offset + 1
      else offset
    in
    String.sub source offset (String.length source - offset)
  else source

let flush_compile_jobs (jobs : compile_job list) =
  match jobs with
  | [] -> ()
  | _ -> (
      let dir = test_dir () in
      let ml_path = Filename.concat dir "compile_batch.ml" in
      let source =
        String.concat "\n"
          [
            native_stdlib_prelude ();
            (jobs
            |> List.mapi (fun index (job : compile_job) ->
                   wrapped_module index job.ocaml_source)
            |> String.concat "\n");
          ]
      in
      write_file ml_path source;
      match Sys.command (compile_only_command dir ml_path) with
      | 0 -> ()
      | code ->
          List.iter
            (compile_job_immediately ~prelude:(native_stdlib_prelude ()))
            jobs;
          failwith
            (Printf.sprintf
               "batched generated OCaml failed with exit code %d, but isolated \
                cases passed"
               code))

let run_marker phase index = Printf.sprintf "__LG_TEST_%s_%04d__\n" phase index

let wrapped_run_module index (job : run_job) =
  Printf.sprintf
    "let () =\n  print_string %S;\n  try\n    let module Case_%04d = struct\n%s\nend in\n    \
     print_string %S\n  with exn ->\n    prerr_endline (\"FAILED RUN JOB: \" ^ %S);\n    raise exn\n"
    (run_marker "BEGIN" index)
    index job.ocaml_source (run_marker "END" index) job.name

let chunks_of count values =
  let rec take remaining taken values =
    if remaining = 0 then (List.rev taken, values)
    else
      match values with
      | [] -> (List.rev taken, [])
      | value :: rest -> take (remaining - 1) (value :: taken) rest
  in
  let rec chunks accumulated values =
    match values with
    | [] -> List.rev accumulated
    | _ ->
        let chunk, rest = take count [] values in
        chunks (chunk :: accumulated) rest
  in
  chunks [] values

let compile_commands_in_parallel commands =
  flush_all ();
  let pids =
    List.map
      (fun command ->
        match Unix.fork () with
        | 0 -> exit (Sys.command command)
        | pid -> pid)
      commands
  in
  List.for_all
    (fun pid ->
      match snd (Unix.waitpid [] pid) with
      | Unix.WEXITED 0 -> true
      | Unix.WEXITED _ | Unix.WSIGNALED _ | Unix.WSTOPPED _ -> false)
    pids

let flush_run_jobs (jobs : run_job list) =
  match jobs with
  | [] -> ()
  | _ -> (
      let dir = test_dir () in
      let output_path = Filename.concat dir "run_batch.out" in
      let batches = chunks_of 24 jobs in
      let batch_files =
        batches
        |> List.mapi (fun batch_index jobs ->
               let basename = Printf.sprintf "run_batch_%03d" batch_index in
               let ml_path = Filename.concat dir (basename ^ ".ml") in
               let cmo_path = Filename.concat dir (basename ^ ".cmo") in
              let source =
                 String.concat "\n"
                   [
                     native_stdlib_prelude ();
                     (jobs
                     |> List.mapi wrapped_run_module
                     |> String.concat "\n");
                   ]
               in
               write_file ml_path source;
               (cmo_path, compile_only_command dir ml_path))
      in
      let expected =
        batches
        |> List.concat_map (fun jobs ->
               jobs
               |> List.mapi (fun index job ->
                      ignore job.name;
                      run_marker "BEGIN" index ^ job.expected_output
                      ^ run_marker "END" index))
        |> String.concat ""
      in
      let cmo_paths = List.map fst batch_files in
      let compile_commands = List.map snd batch_files in
      let run_cmd =
        run_compiled_module_command dir cmo_paths output_path
      in
      if not (compile_commands_in_parallel compile_commands) then (
        batches
        |> List.concat
        |> List.iteri (fun index job ->
               let basename = Printf.sprintf "run_isolated_%04d" index in
               let ml_path = Filename.concat dir (basename ^ ".ml") in
               write_file ml_path
                 (String.concat "\n"
                    [ native_stdlib_prelude (); wrapped_run_module 0 job ]);
               if Sys.command (compile_only_command dir ml_path) <> 0 then
                 Printf.eprintf "FAILED GENERATED COMPILE: %s\n%!" job.name);
        failwith "batched generated OCaml failed")
      else
      match Sys.command run_cmd with
      | code when code <> 0 ->
          failwith
            (Printf.sprintf "batched generated module failed with exit code %d"
               code)
      | _ -> (
          let actual = read_file output_path in
          if actual <> expected then
            let indexed_jobs =
              batches
              |> List.concat_map (fun jobs -> List.mapi (fun index job -> (index, job)) jobs)
            in
            let starts_with_at text offset prefix =
              offset + String.length prefix <= String.length text
              && String.sub text offset (String.length prefix) = prefix
            in
            let find_from text offset pattern =
              let rec loop index =
                if index + String.length pattern > String.length text then None
                else if starts_with_at text index pattern then Some index
                else loop (index + 1)
              in
              loop offset
            in
            let rec compare_jobs offset mismatches = function
              | [] ->
                  let mismatches =
                    if offset = String.length actual then mismatches
                    else
                      Printf.sprintf "unexpected trailing data: %S"
                        (String.sub actual offset (String.length actual - offset))
                      :: mismatches
                  in
                  if mismatches <> [] then
                    failwith
                      ("generated output mismatches:\n"
                      ^ String.concat "\n" (List.rev mismatches))
              | (index, (job : run_job)) :: rest ->
                  let begin_marker = run_marker "BEGIN" index in
                  let end_marker = run_marker "END" index in
                  if not (starts_with_at actual offset begin_marker) then
                    failwith
                      (Printf.sprintf
                         "batched generated output lost marker before %s" job.name)
                  else
                    let content_start = offset + String.length begin_marker in
                    (match find_from actual content_start end_marker with
                    | None ->
                        failwith
                          (Printf.sprintf
                             "batched generated output lost end marker for %s"
                             job.name)
                    | Some content_end ->
                        let output =
                          String.sub actual content_start
                            (content_end - content_start)
                        in
                        let mismatches =
                          if output = job.expected_output then mismatches
                          else
                            Printf.sprintf "%s: expected %S, got %S" job.name
                              job.expected_output output
                            :: mismatches
                        in
                        compare_jobs
                          (content_end + String.length end_marker)
                          mismatches rest)
            in
            compare_jobs 0 [] indexed_jobs))

let assert_ocaml_compiles name ocaml_source =
  pending_compile_jobs :=
    { name; ocaml_source = strip_native_stdlib_prelude ocaml_source }
    :: !pending_compile_jobs

let assert_ocaml_runs name expected_output ocaml_source =
  pending_run_jobs :=
    {
      name;
      expected_output;
      ocaml_source = strip_native_stdlib_prelude ocaml_source;
    }
    :: !pending_run_jobs

