let test_type_relations_are_explicit_and_strict () =
  if Lg.Types.equal Lg.Types.TUnknown Lg.Types.TInt then
    failwith "unknown must not be strictly equal to int";
  let name = Lg.Types.make_field ":name" Lg.Types.TString in
  let narrow = Lg.Types.TRecord [ name ] in
  let wide =
    Lg.Types.TRecord [ name; Lg.Types.make_field ":age" Lg.Types.TInt ]
  in
  if not (Lg.Types.row_compatible ~expected:narrow ~actual:wide) then
    failwith "wider structural records must remain row-compatible";
  let generated =
    Lg.Types.named_record ~type_name:"t1" ~set_module_name:"Set_t1"
      [ name; Lg.Types.make_field ":age" Lg.Types.TInt ]
  in
  if not (Lg.Types.row_compatible ~expected:narrow ~actual:generated) then
    failwith "generated records must remain row-compatible with structural rows";
  if
    not
      (Lg.Types.defer_to_ocaml ~expected:(Lg.Types.TOcaml "user_id")
         ~actual:Lg.Types.TInt)
  then failwith "opaque OCaml relationships must be explicitly deferred"

let test_type_solver_preserves_shared_and_independent_variables () =
  let open Lg.Types in
  let template =
    TTuple
      [
        TVar "value";
        TFn ([ TVar "value"; TVar "other" ], TVar "other");
      ]
  in
  let actual = TTuple [ TInt; TFn ([ TInt; TString ], TString) ] in
  let substitutions =
    Lg.Type_solver.unify Lg.Type_solver.empty template actual
    |> Result.fold ~ok:Fun.id ~error:(fun _ ->
           failwith "compatible shared constraints must unify")
  in
  if Lg.Type_solver.apply substitutions (TVar "value") <> TInt then
    failwith "shared variables must resolve through every occurrence";
  if Lg.Type_solver.apply substitutions (TVar "other") <> TString then
    failwith "independent variables must retain independent solutions";
  let preserved =
    Lg.Type_solver.unify substitutions (TVar "value") TUnknown
    |> Result.fold ~ok:Fun.id ~error:(fun _ ->
           failwith "unknown evidence must not conflict")
  in
  if Lg.Type_solver.apply preserved (TVar "value") <> TInt then
    failwith "unknown evidence must not erase a concrete solution";
  match
    Lg.Type_solver.unify Lg.Type_solver.empty (TVar "recursive")
      (TVector (TVar "recursive"))
  with
  | Error _ -> ()
  | Ok _ -> failwith "recursive substitutions must fail the occurs check"

let test_type_schemes_distinguish_declared_and_inferred_variables () =
  let open Lg.Types in
  let inferred = Lg.Type_solver.fresh () in
  let inferred_scheme =
    Lg.Type_solver.generalize (TFn ([ inferred ], inferred))
  in
  (match inferred_scheme.quantified with
  | [ Inferred_variable _ ] -> ()
  | _ -> failwith "inferred metavariables must retain their category");
  let declared_scheme =
    Lg.Type_solver.generalize
      (TFn ([ TVar "value"; TVar "value" ], TVar "value"))
  in
  match declared_scheme.quantified with
  | [ Declared_variable "value" ] -> ()
  | _ -> failwith "declared variables must retain their category"

let test_type_scheme_instantiation_preserves_shared_identity () =
  let open Lg.Types in
  let inferred = Lg.Type_solver.fresh () in
  let scheme = Lg.Type_solver.generalize (TFn ([ inferred ], inferred)) in
  let first = Lg.Type_solver.instantiate scheme in
  let second = Lg.Type_solver.instantiate scheme in
  match (first, second) with
  | TFn ([ TMeta first_parameter ], TMeta first_return),
    TFn ([ TMeta second_parameter ], TMeta second_return) ->
      if first_parameter.id <> first_return.id then
        failwith "one instantiation must preserve shared occurrences";
      if second_parameter.id <> second_return.id then
        failwith "one instantiation must preserve shared occurrences";
      if first_parameter.id = second_parameter.id then
        failwith "separate instantiations must use fresh metavariables"
  | _ -> failwith "inferred schemes must instantiate to metavariables"

let test_inferred_type_scheme_names_are_canonical () =
  let open Lg.Types in
  let first = Lg.Type_solver.generalize (TVector (Lg.Type_solver.fresh ())) in
  let second = Lg.Type_solver.generalize (TVector (Lg.Type_solver.fresh ())) in
  if
    not
      (equal
         (Lg.Type_solver.canonical_scheme_body first)
         (Lg.Type_solver.canonical_scheme_body second))
  then
    failwith "alpha-equivalent inferred schemes must have stable bodies"

