let test_compiler_phases_have_explicit_boundaries () =
  let state = Lg.Compiler_state.empty in
  if Lg.Compiler_environment.to_bindings state.env <> [] then
    failwith "compiler state should start with an empty environment";
  let binding = Lg.Types.binding "value" Lg.Types.TInt in
  let env = Lg.Compiler_environment.add "value" binding state.env in
  let resolved = Lg.Resolver.lookup_binding "" env "value" |> expect_ok in
  if resolved.ty <> Lg.Types.TInt then
    failwith "resolver should return the typed binding";
  ignore (Lg.Lowering.structure_of_located_items []);
  let expression =
    Lg.Expression_elaborator.compile_expr "" Lg.Compiler_environment.empty
      (Lg.Ast.FInt 1)
      |> expect_ok
    in
    if expression.ty <> Lg.Types.TInt then
      failwith "expression elaboration should have one owner";
    match
    Lg.Top_level_elaborator.compile "" Lg.Compiler_environment.empty 1
      (Lg.Ast.FInt 1)
      |> expect_ok
    with
  | _, _, _, Lg.Lowered.Value_binding _ -> (
        if
          not
          (Lg.Expression_support.branch_types_compatible Lg.Types.TInt
             Lg.Types.TInt)
        then failwith "expression semantic helpers should have one owner";
        let parts : Lg.Expression_support.compiled_fn_parts =
          {
            param_bindings = [ ("x", Lg.Types.binding "x" Lg.Types.TInt) ];
            param_identities = [ None ];
            destructured_bindings = [];
            return_param_index_hint = None;
            body =
              Lg.Types.typed_ir Lg.Types.TInt (Lg.Semantic_ir.Ident "x");
          }
        in
        let fn = Lg.Function_elaborator.fn_code parts in
        if fn.ty <> Lg.Types.TFn ([ Lg.Types.TInt ], Lg.Types.TInt) then
          failwith "function elaboration should have one owner";
        let conditional =
          let operations =
            Lg.Special_form_elaborator.create
              ~compile_expr:Lg.Expression_elaborator.compile_expr
              ~dynamic_unpack:Lg.Call_elaborator.dynamic_unpack
              ~pack_dynamic_value:Lg.Call_elaborator.pack_dynamic_value
              ~pack_constrained_value:Lg.Call_elaborator.pack_constrained_value
              ~argument_compatible:Lg.Call_elaborator.argument_compatible
          in
        operations.compile_if "" Lg.Compiler_environment.empty
          (Lg.Ast.FBool true) (Lg.Ast.FInt 1) (Lg.Ast.FInt 2)
          |> expect_ok
        in
        if conditional.ty <> Lg.Types.TInt then
          failwith "special-form elaboration should have one owner";
        let call =
          let operations =
            Lg.Call_elaborator.create
              ~compile_expr:Lg.Expression_elaborator.compile_expr
          in
        operations.compile_call "" Lg.Compiler_environment.empty "__lg_add"
          [ Lg.Ast.FInt 1; Lg.Ast.FInt 1 ]
          |> expect_ok
        in
        if call.ty <> Lg.Types.TInt then
          failwith "call elaboration should have one owner";
        let list =
          let operations =
            Lg.Collection_operation_elaborator.create
              ~compile_expr:Lg.Expression_elaborator.compile_expr
            ~pack_dynamic_value:(fun _env _expected value ->
              Ok value.Lg.Types.semantic_expr)
            ~dynamic_unpack:(fun _env _expected expression -> Ok expression)
          in
        operations.compile_list "" Lg.Compiler_environment.empty
            [ Lg.Ast.FInt 1; Lg.Ast.FInt 2 ]
          |> expect_ok
        in
        if list.ty <> Lg.Types.TList Lg.Types.TInt then
          failwith "collection operation elaboration should have one owner";
        let composed =
          let operations =
            Lg.Function_combinator_elaborator.create
              ~compile_expr:Lg.Expression_elaborator.compile_expr
              ~dynamic_unpack:(fun _ _ expression -> Ok expression)
              ~pack_dynamic_value:(fun _env _expected value ->
                Ok value.Lg.Types.semantic_expr)
              ~pack_constrained_value:(fun _env _expected value ->
                Ok value.Lg.Types.semantic_expr)
              ~adapt_value_to_type:(fun _env _expected value ->
                Ok value.Lg.Types.semantic_expr)
          in
        let comp_env =
          Lg.Compiler_environment.add "positive"
            (Lg.Types.binding "positive"
               (Lg.Types.TFn ([ Lg.Types.TInt ], Lg.Types.TBool)))
            Lg.Compiler_environment.empty
        in
        operations.compile_static_comp "" comp_env [ Lg.Ast.FSymbol "positive" ]
          |> expect_ok
        in
      (match composed.ty with
      | Lg.Types.TFn ([ Lg.Types.TInt ], Lg.Types.TBool) -> ()
      | _ ->
        failwith "core higher-order call elaboration should have one owner";
      );
        let context =
          Lg.Elaboration_context.create
            ~compile_expr:Lg.Expression_elaborator.compile_expr
        in
        let special_forms = context.special_forms in
        if special_forms != context.special_forms then
          failwith "elaboration domains should be initialized once";
        let conditional =
          special_forms.compile_if "" Lg.Compiler_environment.empty
            (Lg.Ast.FBool true) (Lg.Ast.FInt 1) (Lg.Ast.FInt 2)
          |> expect_ok
        in
        if conditional.ty <> Lg.Types.TInt then
          failwith "typed elaboration context should route special forms";
        let calls = context.calls in
        if calls != context.calls then
          failwith "call elaboration should be initialized once";
        let result =
          calls.compile_call "" Lg.Compiler_environment.empty "__lg_add"
            [ Lg.Ast.FInt 1; Lg.Ast.FInt 1 ]
          |> expect_ok
        in
        if result.ty <> Lg.Types.TInt then
          failwith "typed elaboration context should route calls";
        let scalar =
        Lg.Expression_elaborator.compile_expr "" Lg.Compiler_environment.empty
          (Lg.Ast.FInt 7)
          |> expect_ok
        in
        (match Lg.Semantic_ir.unlocated scalar.semantic_expr with
        | Lg.Semantic_ir.Int 7 -> ()
        | _ -> failwith "typed expressions should carry semantic AST nodes");
      match Lg.Lowering.expression scalar.semantic_expr with
        | Lg.Ocaml_ir.Int 7 -> ()
        | _ -> failwith "semantic lowering should produce backend IR")
    | _ -> failwith "top-level elaboration should have one owner"

let test_compiler_environment_finds_bindings_without_materializing_all () =
  let env =
    Lg.Compiler_environment.empty
    |> Lg.Compiler_environment.add "ordinary/value"
         (Lg.Types.binding "ordinary_value" Lg.Types.TInt)
    |> Lg.Compiler_environment.add "target/value"
         (Lg.Types.binding "target_value" Lg.Types.TString)
  in
  match
    Lg.Compiler_environment.find_map
      (fun name binding -> if name = "target/value" then Some binding else None)
      env
  with
  | Some binding when binding.Lg.Types.ty = Lg.Types.TString -> ()
  | _ -> failwith "environment find_map must return the matching binding"

let test_compiler_environment_indexes_bindings_by_local_name () =
  let env =
    Lg.Compiler_environment.empty
    |> Lg.Compiler_environment.add "first/Value"
         (Lg.Types.binding "first_value" Lg.Types.TInt)
    |> Lg.Compiler_environment.add "second/Value"
         (Lg.Types.binding "second_value" Lg.Types.TString)
    |> Lg.Compiler_environment.add "second/Other"
         (Lg.Types.binding "second_other" Lg.Types.TBool)
  in
  let types =
    Lg.Compiler_environment.bindings_named "Value" env
    |> List.map (fun (binding : Lg.Types.binding) -> binding.ty)
    |> List.sort_uniq Stdlib.compare
  in
  if types <> [ Lg.Types.TInt; Lg.Types.TString ] then
    failwith "local-name binding index must include every matching namespace"

let test_compiler_environment_indexes_namespace_prefixes () =
  let env =
    Lg.Compiler_environment.empty
    |> Lg.Compiler_environment.add "people/user"
         (Lg.Types.binding "People.user" Lg.Types.TString)
    |> Lg.Compiler_environment.add "__record/people/Person"
         (Lg.Types.binding "People.person"
            (Lg.Types.named_record ~type_name:"Person"
               ~set_module_name:"Person_set" []))
    |> Lg.Compiler_environment.add "people.address/city"
         (Lg.Types.binding "People.Address.city" Lg.Types.TString)
    |> Lg.Compiler_environment.add "unrelated/value"
         (Lg.Types.binding "Unrelated.value" Lg.Types.TInt)
  in
  let keys env =
    Lg.Compiler_environment.namespace_binding_entries "people" env
    |> List.map fst |> List.sort String.compare
  in
  let expected =
    [ "__record/people/Person"; "people.address/city"; "people/user" ]
  in
  if keys env <> expected then
    failwith "namespace index must include values, records, and nested modules";
  let removed =
    Lg.Compiler_environment.remove "__record/people/Person" env
  in
  if keys removed <> [ "people.address/city"; "people/user" ] then
    failwith "namespace index must discard removed bindings"

let test_unresolved_declaration_index_tracks_aliases_and_overloads () =
  let declared ?(overload_targets = []) ocaml_name =
    { (Lg.Types.binding ocaml_name (Lg.Types.TOcaml "__declared_fn")) with
      overload_targets;
    }
  in
  let forward ?(overload_targets = []) ocaml_name =
    { (Lg.Types.binding ocaml_name Lg.Types.TInt) with
      forward_declared = true;
      overload_targets;
    }
  in
  let env =
    Lg.Compiler_environment.empty
    |> Lg.Compiler_environment.add "first/value" (declared "shared")
    |> Lg.Compiler_environment.add "second/value"
         (forward ~overload_targets:[ "shared$arity2" ] "shared")
  in
  if not (Lg.Compiler_environment.unresolved_declaration "shared$arity2" env)
  then failwith "overload targets must remain unresolved declarations";
  let env = Lg.Compiler_environment.remove "first/value" env in
  if not (Lg.Compiler_environment.unresolved_declaration_binding "shared" env)
  then failwith "removing one alias must preserve another declaration";
  let env =
    Lg.Compiler_environment.add "second/value"
      (Lg.Types.binding "shared" Lg.Types.TInt)
      env
  in
  if Lg.Compiler_environment.unresolved_declaration "shared" env then
    failwith "replacing the final forward declaration must clear the index"

let test_record_lookup_cost_is_independent_of_unrelated_bindings () =
  let record_ty =
    Lg.Types.named_record ~type_name:"Wanted" ~set_module_name:"Wanted_set" []
  in
  let env =
    Lg.Compiler_environment.empty
    |> Lg.Compiler_environment.add "__record/requested/Stored"
         (Lg.Types.binding "stored" record_ty)
  in
  let env =
    List.init 20_000 Fun.id
    |> List.fold_left
         (fun env index ->
           Lg.Compiler_environment.add
             (Printf.sprintf "noise-%05d/value" index)
             (Lg.Types.binding (Printf.sprintf "noise_%05d" index) Lg.Types.TInt)
             env)
         env
  in
  let unrelated_record =
    Lg.Types.binding "unrelated_record"
      (Lg.Types.named_record ~type_name:"Unrelated"
         ~set_module_name:"Unrelated_set" [])
  in
  let env =
    List.init 10_000 Fun.id
    |> List.fold_left
         (fun env index ->
           let scope = if index mod 2 = 0 then "other" else "requested" in
           Lg.Compiler_environment.add
             (Printf.sprintf "__record/%s/Unrelated%05d" scope index)
             unrelated_record env)
         env
  in
  Gc.full_major ();
  let before = Gc.allocated_bytes () in
  for _ = 1 to 25 do
    match Lg.Resolver.lookup_record_type "requested" env "Wanted" with
    | Ok record when String.equal record.type_name "Wanted" -> ()
    | Ok _ -> failwith "record fallback lookup returned the wrong record"
    | Error error ->
        failwith ("record fallback lookup failed: " ^ error.Lg.Error.message)
  done;
  let allocated = Gc.allocated_bytes () -. before in
  if allocated > 500_000. then
    failwith
      (Printf.sprintf
         "record fallback lookup allocated %.0f bytes for unrelated bindings"
         allocated)

let test_record_lookup_index_tracks_removal_and_ambiguity () =
  let record_binding emitted_name =
    Lg.Types.binding emitted_name
      (Lg.Types.named_record ~type_name:"Wanted" ~set_module_name:"Wanted_set" [])
  in
  let first_key = "__record/requested/StoredFirst" in
  let env =
    Lg.Compiler_environment.empty
    |> Lg.Compiler_environment.add first_key (record_binding "stored_first")
  in
  let removed = Lg.Compiler_environment.remove first_key env in
  (match Lg.Resolver.lookup_record_type "requested" removed "Wanted" with
  | Error _ -> ()
  | Ok _ -> failwith "removed record remained visible to fallback lookup");
  let ambiguous =
    env
    |> Lg.Compiler_environment.add "__record/requested/StoredSecond"
         (record_binding "stored_second")
  in
  match Lg.Resolver.lookup_record_type "requested" ambiguous "Wanted" with
  | Error _ -> ()
  | Ok _ -> failwith "ambiguous record fallback lookup must be rejected"

