    let _, consumer_ocaml =
      Lg.Compiler.compile_chunk ~target state consumer_source |> expect_ok
    in
    ( stdlib.ocaml_source ^ "\n" ^ provider_ocaml ^ "\n" ^ consumer_ocaml,
      consumer_ocaml )
