  in
  let _, outputs =
    compile_datascript_sources ~check_ocaml:false Lg.Target.Native
      initial_state
      (current_datascript_sources ()
      @ [
          source "test/datascript/upstream/pull_parser.cljc";
          source "test/datascript/upstream/pull_api.cljc";
        ])
