    (db/default-options)))

(def named-database
  (query/q
    '[:find ?a ?v
      :in $db ?e
      :where [$db ?e ?a ?v]]
    database
    1))

(def database-and-relation
  (query/q
    '[:find ?e ?email
      :in $ $contacts
      :where [?e :name ?name]
             [$contacts ?name ?email]]
    database
    [["Ivan" "ivan@example.com"]
     ["Petr" "petr@example.com"]]))

(def two-relations
  (query/q
    '[:find ?name ?age
      :in $names $ages
      :where [$names ?id ?name]
             [$ages ?id ?age]]
    [[1 "Ivan"] [2 "Petr"]]
