  (if-some [rows (query-types/output-relation two-relations)]
    (= 1 (count rows))
    false))
(println
  (if-some [rows (query-types/output-relation reordered-source)]
    (= 1 (count rows))
    false))
(println
  (if-some [rows (query-types/output-relation empty-relation)]
    (empty? rows)
    false))
(println missing-source-rejected?)
|}
  in
