  (query/q
   '[:find ?n
     :where [(identity 1) ?n]]))

(def ground-result
  (query/q
   '[:find ?n
     :where [(ground 2) ?n]]))

(def add-result
  (query/q
   '[:find ?sum
     :where [(+ 15 22) ?sum]]))

(def bound-add-result
  (query/q
   '[:find ?age ?next
     :in [?age ...]
     :where [(+ ?age 5) ?next]]
   [10 20 30]))

(def conflict-result
  (query/q
