     :where [(ground [:a :e :i :o :u]) [?vowel ...]]]))

(def relation-result
  (query/q
   '[:find ?left ?right
     :where
     [(ground [[:a :ignored :c]
               [:d :ignored :f]])
      [[?left _ ?right] ...]]]))

