 (if-some [rows (query-types/output-relation relation-result)]
   (and
    (= 2 (count rows))
    (some
     (fn [row]
       (and (= ":a" (result-keyword row 0))
            (= ":c" (result-keyword row 1))))
     rows)
    (some
     (fn [row]
       (and (= ":d" (result-keyword row 0))
            (= ":f" (result-keyword row 1))))
     rows))
   false))
