  (if-some [rows (query-types/output-relation output)]
    (count rows)
    -1))

(def simple
  (query/q
   '[:find ?e
     :where
     [?e :name]
     (not [?e :name "Ivan"])]
   database))

(def multi-clause
  (query/q
   '[:find ?e
     :where
     [?e :name]
     (not
      [?e :name "Ivan"]
      [?e :age 10])]
   database))

