 (= 0
    (match-count
     value-retracted 1 :name
     (Datascript_runtime.Data_value.String "Ivan"))))
(println
 (= 0
    (match-count
     attribute-retracted 1 :age
     (Datascript_runtime.Data_value.Int 19))))
