let test_custom_compare_and_set_dispatches () =
  let source =
    {|
(type-record box (cell :ref<int>))
(extend-type box
  IDeref
  (-deref [box] @(:cell box))
  IAtom
  (-compare-and-set! [box old-value new-value]
    (let [cell (:cell box)]
      (if (identical? @cell old-value)
        (do
            (reset! cell new-value)
            true)
          false)))
  IReset
  (-reset! [box new-value]
    (let [cell (:cell box)]
      (reset! cell new-value)))
  ISwap
  (-swap! [box update-value]
    (let [cell (:cell box)
          new-value (update-value @cell)]
      (reset! cell new-value))))
(def value (record box (cell (atom 1))))
(def evaluations (atom 0))
(defn evaluated-value []
  (do
    (swap! evaluations inc)
    value))

(println
  (str
    (compare-and-set! value 1 2) ":"
    @value ":"
    (compare-and-set! value 1 3) ":"
    @value ":"
    (reset! value 4) ":"
    @value ":"
    (swap! value inc) ":"
    @value ":"
    (swap! value + 2) ":"
    @value ":"
    (swap! value + 3 4) ":"
    @value ":"
    (swap! (evaluated-value) + 1 2 3 4) ":"
    @value ":"
    @evaluations))
|}
  in
  let native_source = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs "custom_compare_and_set_dispatches"
    "true:2:false:2:4:4:5:5:7:7:14:14:24:24:1\n" native_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok)

