let test_update_preserves_named_records_with_opaque_fields () =
  let source =
    {|
(type-record tree [value]
  (item :value))
(type-record database
  (root :ref<option<tree<int>>>)
  (max-eid :int)
  (schema :map<keyword;int>))
(defprotocol IDB
  (valid-db? [db] :bool))
(extend-type database IDB
  (valid-db? [_db] true))
(defrecord TxReport [^database db-after])
(def tx0 100)
(defn new-eid? [db eid]
  (and (> eid (:max-eid db))
       (< eid tx0)))
(defn advance-max-eid [db eid]
  (cond-> db
    (new-eid? db eid)
    (assoc :max-eid eid)))
(defn update-rschema [db]
  (assoc db :max-eid 42))
(defn update-schema [db _datom]
  db)
(defn keep-schema [schema]
  schema)
(defn checked-db [db valid?]
  (if valid?
    (update-in db [:schema] keep-schema)
    (Stdlib.invalid_arg "invalid db")))
(defn with-datom [db datom]
  (satisfies? IDB db)
  (let [schema? true]
    (if true
      (cond-> db
        true (advance-max-eid datom)
        schema? (-> (update-schema datom)
                    (checked-db true)
                    update-rschema))
      db)))
(defn allocate-eid [report eid]
  (let [m report
        k :db-after]
    (assoc m k (advance-max-eid (get m k) eid))))
(def initial-db
  (record database
    (root (volatile! (Some (record tree (item 7)))))
    (max-eid 1)
    (schema {:version 9})))
(def initial-report (TxReport. initial-db))
(def updated
  (allocate-eid initial-report 42))
(def updated-db
  (with-datom (:db-after updated) 42))
(def db updated-db)
(println
  [(:max-eid db)
   (match (deref (:root db))
     (Some root) (:item root)
     None 0)])
(println (get (:schema db) :version 0))
|}
  in
  let ocaml_source = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs "update_preserves_named_records_with_opaque_fields"
    "[42 7]\n9\n" ocaml_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok);
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Js_of_ocaml source |> expect_ok)

