let test_source_some_and_boolean_predicates_preserve_static_contracts () =
  let source =
    {|
(ns source-predicate-app
  (:require [cljs.core :as core :refer [some? boolean?]]))

(def evaluations (atom 0))
(defn int-present? [^:int value] (some? value))
(defn string-present? [^:string value] (core/some? value))
(defn optional-present? [^:option<int> value]
  (clojure.core/some? value))
(defn optional-inc [^:option<int> value]
  (if (some? value) (inc value) 0))

(println (int-present? 1))
(println (string-present? "value"))
(println (optional-present? (Some 2)))
(println (optional-present? nil))
(println (= 3 (optional-inc (Some 2))))
(println (= 0 (optional-inc nil)))
(println (some? (do (swap! evaluations inc) nil)))
(println (core/boolean? (do (swap! evaluations inc) true)))
(println (boolean? false))
(println (clojure.core/boolean? 1))
(println (boolean? "false"))
(println (boolean? nil))
(println (= 2 @evaluations))
|}
  in
  let native_source =
    compile_with_stdlib Lg.Target.Native "test/source_predicates.cljc" source
  in
  if string_contains_substring native_source "Runtime_dynamic" then
    failwith "source predicates must preserve static values";
  assert_ocaml_runs "source_some_and_boolean_predicates"
    "true\ntrue\ntrue\nfalse\ntrue\ntrue\nfalse\ntrue\ntrue\nfalse\nfalse\nfalse\ntrue\n"
    native_source;
  let melange_source =
    compile_with_stdlib Lg.Target.Melange "test/source_predicates.cljc" source
  in
  if string_contains_substring melange_source "Runtime_dynamic" then
    failwith "Melange source predicates must preserve static values";
  compile_with_stdlib_result Lg.Target.Native "test/some_zero_arity.cljc"
    {|(def result (some?))|}
  |> expect_error_contains "unsupported macro arity 0";
  compile_with_stdlib_result Lg.Target.Native "test/some_two_arity.cljc"
    {|(def result (some? 1 2))|}
  |> expect_error_contains "unsupported macro arity 2";
  compile_with_stdlib_result Lg.Target.Native "test/boolean_zero_arity.cljc"
    {|(def result (boolean?))|}
  |> expect_error_contains "unsupported macro arity 0";
  compile_with_stdlib_result Lg.Target.Native "test/boolean_two_arity.cljc"
    {|(def result (boolean? true false))|}
  |> expect_error_contains "unsupported macro arity 2"

let test_source_collection_and_scalar_predicates_match_clojurescript () =
  let source =
    {|
(ns source-protocol-predicate-app
  (:require [cljs.core :as core
             :refer [empty? integer? ident? counted? seqable?]]))

(def evaluations (atom 0))
(println (empty? nil))
(println (empty? []))
(println (empty? (list)))
(println (empty? ""))
(println (empty? {}))
(println (empty? #{}))
(println (core/empty? [1]))
(println (clojure.core/empty? "x"))
(println (integer? 1))
(println (integer? 1.0))
(println (core/integer? "1"))
(println (ident? :name))
(println (ident? 'name))
(println (clojure.core/ident? "name"))
(println (counted? [1]))
(println (counted? (list 1)))
(println (core/counted? (array-values 1)))
(println (counted? {}))
(println (counted? (seq [1])))
(println (seqable? nil))
(println (seqable? (array-values 1)))
(println (seqable? {}))
(println (seqable? (seq [1])))
(println (seqable? 1))
(println (empty? (do (swap! evaluations inc) [])))
(println (= 1 @evaluations))
(println (integer? (do (swap! evaluations inc) 1)))
(println (= 2 @evaluations))
(println (ident? (do (swap! evaluations inc) :name)))
(println (= 3 @evaluations))
(println (counted? (do (swap! evaluations inc) [1])))
(println (= 4 @evaluations))
(println (seqable? (do (swap! evaluations inc) [1])))
(println (= 5 @evaluations))
(println (= 5 @evaluations))
|}
  in
  let native_source =
    compile_with_stdlib Lg.Target.Native "test/source_protocol_predicates.cljc"
      source
  in
  if string_contains_substring native_source "Runtime_dynamic" then
    failwith "source protocol predicates must preserve static values";
  assert_ocaml_runs "source_collection_and_scalar_predicates"
    "true\ntrue\ntrue\ntrue\ntrue\ntrue\nfalse\nfalse\ntrue\nfalse\nfalse\ntrue\ntrue\nfalse\ntrue\ntrue\ntrue\ntrue\nfalse\ntrue\ntrue\ntrue\ntrue\nfalse\ntrue\ntrue\ntrue\ntrue\ntrue\ntrue\ntrue\ntrue\ntrue\ntrue\ntrue\n"
    native_source;
  let melange_source =
    compile_with_stdlib Lg.Target.Melange
      "test/source_protocol_predicates.cljc" source
  in
  if string_contains_substring melange_source "Runtime_dynamic" then
    failwith "Melange source protocol predicates must preserve static values";
  List.iter
    (fun name ->
      compile_with_stdlib_result Lg.Target.Native
        ("test/" ^ name ^ "_zero_arity.cljc")
        ("(def result (" ^ name ^ "))")
      |> expect_error_contains "unsupported macro arity 0";
      compile_with_stdlib_result Lg.Target.Native
        ("test/" ^ name ^ "_two_arity.cljc")
        ("(def result (" ^ name ^ " 1 2))")
      |> expect_error_contains "unsupported macro arity 2")
    [ "empty?"; "integer?"; "ident?"; "counted?"; "seqable?" ];
  compile_with_stdlib_result Lg.Target.Native "test/empty_non_seqable.cljc"
    {|(def result (empty? 1))|}
  |> expect_error_contains "seq expects a seqable value"

let test_source_not_empty_preserves_concrete_collections () =
  let source =
    {|
(ns source-not-empty-app
  (:require [cljs.core :as core :refer [not-empty]]))

(def evaluations (atom 0))
(def ^:map<keyword;int> populated-map {:answer 42})
(def empty-map (dissoc populated-map :answer))
(def tagged-map
  (with-meta populated-map {:source "upstream"}))

(println (nil? (not-empty nil)))
(println (nil? (not-empty (vector-of :int))))
(println (nil? (not-empty (list-of :int))))
(println (nil? (not-empty (set-of :int))))
(println (nil? (not-empty empty-map)))
(println (nil? (not-empty "")))
(println (nil? (not-empty (array-of :int))))
(println
  (if-some [values (not-empty [1])]
    (= [1 2] (conj values 2))
    false))
(println
  (if-some [values (not-empty (list 1))]
    (= (list 0 1) (conj values 0))
    false))
(println
  (if-some [values (not-empty (hash-set 1))]
    (contains? (conj values 2) 2)
    false))
(println
  (if-some [values (not-empty populated-map)]
    (= 42 (:answer values))
    false))
(println
  (if-some [value (not-empty "Ada")]
    (= "Ada" value)
    false))
(println
  (if-some [values (not-empty (array-values 1 2))]
    (= 2 (alength values))
    false))
(println (nil? (core/not-empty (vector-of :int))))
(println (some? (clojure.core/not-empty [1])))
(println
  (if-some [value (not-empty tagged-map)]
    (= "upstream" (:source (meta value)))
    false))
(println (nil? (not-empty (do (swap! evaluations inc) []))))
(println (= 1 @evaluations))
|}
  in
  let expected = String.concat "" (List.init 18 (fun _ -> "true\n")) in
  let native_source =
    compile_with_stdlib Lg.Target.Native "test/source_not_empty.cljc" source
  in
  if string_contains_substring native_source "Runtime_dynamic" then
    failwith "source not-empty must preserve static collection types";
  assert_ocaml_runs "source_not_empty_preserves_concrete_collections" expected
    native_source;
  let melange_source =
    compile_with_stdlib Lg.Target.Melange "test/source_not_empty.cljc" source
  in
  if string_contains_substring melange_source "Runtime_dynamic" then
    failwith "Melange source not-empty must preserve static collection types";
  compile_with_stdlib_result Lg.Target.Native
    "test/not_empty_zero_arity.cljc" {|(def result (not-empty))|}
  |> expect_error_contains "unsupported macro arity 0";
  compile_with_stdlib_result Lg.Target.Native
    "test/not_empty_two_arity.cljc" {|(def result (not-empty [] []))|}
  |> expect_error_contains "unsupported macro arity 2";
  compile_with_stdlib_result Lg.Target.Native
    "test/not_empty_non_seqable.cljc" {|(def result (not-empty 1))|}
  |> expect_error_contains "seq expects a seqable value"

let test_source_static_predicate_family_matches_clojurescript () =
  let predicate_names =
    [
      "nil?";
      "true?";
      "false?";
      "int?";
      "number?";
      "string?";
      "keyword?";
      "symbol?";
      "vector?";
      "list?";
      "seq?";
      "set?";
      "map?";
      "fn?";
      "coll?";
      "associative?";
      "rational?";
      "float?";
      "double?";
      "sequential?";
      "reversible?";
      "sorted?";
    ]
  in
  let source =
    {|
(ns source-static-predicate-app
  (:require [cljs.core :as core
             :refer [nil? true? false? int? number? string? keyword? symbol?
                     vector? list? seq? set? map? fn? coll? associative?
                     rational? float? double? sequential? reversible? sorted?]]))

(def evaluations (atom 0))
(defn identity-fn [value] value)

(println (nil? nil))
(println (not (nil? 0)))
(println (true? true))
(println (false? false))
(println (int? 1))
(println (number? 1.0))
(println (string? "value"))
(println (keyword? :value))
(println (symbol? 'value))
(println (vector? []))
(println (list? (list)))
(println (seq? (seq [1])))
(println (set? #{}))
(println (map? {}))
(println (fn? identity-fn))
(println (coll? (range 2)))
(println (not (coll? "value")))
(println (associative? []))
(println (associative? {}))
(println (not (associative? (list))))
(println (rational? 1))
(println (not (rational? 1.0)))
(println (float? 1.0))
(println (double? 1.0))
(println (sequential? []))
(println (not (sequential? #{})))
(println (not (reversible? "value")))
(println (not (reversible? #{})))
(println (not (sorted? [])))
(println (core/vector? []))
(println (clojure.core/map? {}))

(nil? (do (swap! evaluations inc) nil))
(true? (do (swap! evaluations inc) true))
(false? (do (swap! evaluations inc) false))
(int? (do (swap! evaluations inc) 1))
(number? (do (swap! evaluations inc) 1))
(string? (do (swap! evaluations inc) "value"))
(keyword? (do (swap! evaluations inc) :value))
(symbol? (do (swap! evaluations inc) 'value))
(vector? (do (swap! evaluations inc) []))
(list? (do (swap! evaluations inc) (list)))
(seq? (do (swap! evaluations inc) (seq [1])))
(set? (do (swap! evaluations inc) #{}))
(map? (do (swap! evaluations inc) {}))
(fn? (do (swap! evaluations inc) identity-fn))
(coll? (do (swap! evaluations inc) []))
(associative? (do (swap! evaluations inc) []))
(rational? (do (swap! evaluations inc) 1))
(float? (do (swap! evaluations inc) 1.0))
(double? (do (swap! evaluations inc) 1.0))
(sequential? (do (swap! evaluations inc) []))
(reversible? (do (swap! evaluations inc) []))
(sorted? (do (swap! evaluations inc) []))
(println (= 22 @evaluations))
|}
  in
  let expected = String.concat "" (List.init 32 (fun _ -> "true\n")) in
  let native_source =
    compile_with_stdlib Lg.Target.Native "test/source_static_predicates.cljc"
      source
  in
  if string_contains_substring native_source "Runtime_dynamic" then
    failwith "source static predicates must not introduce dynamic dispatch";
  assert_ocaml_runs "source_static_predicate_family_matches_clojurescript"
    expected native_source;
  let melange_source =
    compile_with_stdlib Lg.Target.Melange "test/source_static_predicates.cljc"
      source
  in
  if string_contains_substring melange_source "Runtime_dynamic" then
    failwith
      "Melange source static predicates must not introduce dynamic dispatch";
  List.iter
    (fun name ->
      compile_with_stdlib_result Lg.Target.Native
        ("test/" ^ name ^ "_source_zero_arity.cljc")
        ("(def result (" ^ name ^ "))")
      |> expect_error_contains "unsupported macro arity 0";
      compile_with_stdlib_result Lg.Target.Native
        ("test/" ^ name ^ "_source_two_arity.cljc")
        ("(def result (" ^ name ^ " 1 2))")
      |> expect_error_contains "unsupported macro arity 2")
    predicate_names

