let test_clojure_walk_rejects_dynamic_source_parameters () =
  let source =
    {|
(ns walk-example
  (:require [clojure.walk :as walk]))

(defn replace-two [^:dynamic value]
  (if (= value 2) 20 value))

(println
  (= {:items [1 {:value 20}]
      :values #{20}}
     (walk/postwalk replace-two
       {:items [1 {:value 2}]
        :values #{2}})))

(defn expand [^:dynamic value]
  (cond
    (= value 1) [2]
    (= value 2) 20
    :else value))

(println (= [[2]] (walk/postwalk expand [1])))
(println (= [[20]] (walk/prewalk expand [1])))
(println
  (= [:new 20]
     (walk/walk replace-two (fn [^:dynamic value] value) [:new 2])))
(println
  (= (assoc {} :new 1)
     (walk/postwalk
       (fn [^:dynamic value] (if (= value :old) :new value))
       {:old 1})))

(def visited (atom 0))
(walk/postwalk
  (fn [^:dynamic value]
    (if (or (= value 1) (= value 2))
      (do (swap! visited inc) value)
      value))
  (map identity [1 2]))
(println (= 2 @visited))
|}
  in
  compile_with_stdlib_result Lg.Target.Native
    "test/clojure_walk_dynamic_source.cljc" source
  |> expect_error_contains "dynamic is not a source type"

