let test_source_cljs_test_nested_async_testing_preserves_context_lifetime () =
  let source =
    {|
(ns app.cljs-test-nested-async
  (:require [cljs.test :refer [async deftest get-current-env is run-tests
                               testing testing-contexts-str]]))

