(defrecord Search [items]
  ICounted
  (-count [search]
    (count
      (->Eduction
        (filter (fn [^Datom datom]
                  (and (some? (.-v datom))
                       (pos? (datom-value datom)))))
        items))))
(defprotocol IProjection
  (-values [projection]))
(defrecord Projection [items]
  IProjection
  (-values [projection]
    (map (fn [^Datom datom]
           (datom-value datom))
      items)))
(def datoms [(Datom. 1 :a true 1)
             (Datom. 2 :a true -1)
             (Datom. 3 :a true 2)])
(println (count (Search. datoms)))
(println (pr-str (-values (Projection. datoms))))
|}
  in
  let ocaml_source = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs "transducer_type_hints_infer_nominal_record_fields"
    "2\n(1 -1 2)\n" ocaml_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok);
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Js_of_ocaml source |> expect_ok)

let test_deftype_methods_flush_after_their_declared_dependencies () =
  let source =
    {|
(declare item-score normalize-score)
(defprotocol Identified
  (-id [item]))
(deftype Item [^int value]
  Identified
  (-id [item] (item-score item)))
(defn item-score [^Item item]
  (normalize-score (.-value item)))
(defn normalize-score [score]
  score)

(declare unrelated)
(defrecord Items [values]
  ICounted
  (-count [items]
    (count
      (filter (fn [^Item item]
                (__lg_pos-predicate (-id item)))
        values))))
(defn unrelated [] 42)

(println (count (Items. [(Item. 1) (Item. -1) (Item. 2)])))
|}
  in
  let ocaml_source = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs
    "deftype_methods_flush_after_their_declared_dependencies" "2\n"
    ocaml_source

let test_protocol_consumers_use_stable_later_implementation_returns () =
  let source =
    {|
(defprotocol Searchable
  (-search [data pattern]))
(defn first-match [data pattern]
  (first (-search data pattern)))
(deftype SearchData [^:vector<int> values]
  Searchable
  (-search [data pattern]
    (if (seq values)
      (Some (seq values))
      None)))
(defn find-value [data]
  (first-match data []))
(println (find-value (SearchData. [42])))
|}
  in
  let ocaml_source = Lg.Compiler.compile_string source |> expect_ok in
  assert_ocaml_runs
    "protocol_consumers_use_stable_later_implementation_returns" "42\n"
    ocaml_source;
  ignore
    (Lg.Compiler.compile_string ~target:Lg.Target.Melange source |> expect_ok)

let test_protocol_function_parameters_keep_nominal_record_types () =
  let source =
    {|
(defrecord Datom [^int value])
(defrecord DB [^int threshold])
(defrecord FilteredDB
  [^DB unfiltered-db
   ^:fn<Datom;bool> pred])

(defprotocol IFilteredView
  (-filter-view
    [database ^:fn<DB;Datom;bool> pred]
    :FilteredDB))

(extend-type DB
  IFilteredView
  (-filter-view
    [database ^:fn<DB;Datom;bool> view-pred]
    (FilteredDB.
      database
      (fn [^Datom datom]
        (view-pred database datom)))))

(extend-type FilteredDB
  IFilteredView
  (-filter-view
    [filtered-db ^:fn<DB;Datom;bool> view-pred]
    (let [original-pred (.-pred filtered-db)
          original-db (.-unfiltered-db filtered-db)]
      (FilteredDB.
        original-db
        (fn [^Datom datom]
          (and
            (original-pred datom)
            (view-pred original-db datom)))))))

(defn ^FilteredDB filter-view
  [database ^:fn<DB;Datom;bool> pred]
  (-filter-view database pred))

(def base (DB. 10))
(def once
  (filter-view
    base
    (fn [^DB database ^Datom datom]
      (> (.-value datom) (.-threshold database)))))
(def twice
  (filter-view
    once
    (fn [^DB database ^Datom datom]
      (< (.-value datom) (+ (.-threshold database) 5)))))
(println
  (str
    ((.-pred twice) (Datom. 12)) ":"
    ((.-pred twice) (Datom. 16))))
|}
  in
  let native_source = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs "protocol_function_parameters_keep_nominal_record_types"
    "true:false\n" native_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok)

let test_cross_namespace_protocol_functions_keep_nominal_record_parameters () =
  let provider =
    {|
(ns app.db)
(defrecord Datom [^int value])
(defrecord DB [^int threshold])
(defrecord FilteredDB
  [^app.db/DB unfiltered-db
   ^:fn<app.db/Datom;bool> pred])
(defprotocol IFilteredView
  (-filter-view
    [database ^:fn<app.db/DB;app.db/Datom;bool> pred]
    :app.db/FilteredDB))
(extend-type DB
  IFilteredView
  (-filter-view
    [database ^:fn<app.db/DB;app.db/Datom;bool> view-pred]
    (FilteredDB.
      database
      (fn [^app.db/Datom datom]
        (view-pred database datom)))))
|}
  in
  let consumer =
    {|
(ns app.core
  (:require [app.db :as db]))
(defn ^app.db/FilteredDB filter-view
  [database ^:fn<app.db/DB;app.db/Datom;bool> pred]
  (db/-filter-view database pred))
(def filtered
  (filter-view
    (db/->DB 10)
    (fn [^app.db/DB database ^app.db/Datom datom]
      (> (.-value datom) (.-threshold database)))))
(println ((.-pred filtered) (db/->Datom 12)))
|}
  in
  let compile target =
    let state, provider_ocaml =
      Lg.Compiler.compile_chunk ~target (stdlib_state target) provider
      |> expect_ok
    in
    let _, consumer_ocaml =
      Lg.Compiler.compile_chunk ~target state consumer |> expect_ok
    in
    provider_ocaml ^ "\n" ^ consumer_ocaml
  in
  let native_source = compile Lg.Target.Native in
  assert_ocaml_runs
    "cross_namespace_protocol_functions_keep_nominal_record_parameters"
    "true\n" native_source;
  ignore (compile Lg.Target.Melange)

let test_protocol_function_parameters_reject_distinct_nominal_records () =
  let source =
    {|
(defrecord Datom [^int value])
(defrecord DB [^int threshold])
(defrecord OtherDB [^int threshold])
(defrecord FilteredDB [])
(defprotocol IFilteredView
  (-filter-view
    [database ^:fn<DB;Datom;bool> pred]
    :FilteredDB))
(extend-type DB
  IFilteredView
  (-filter-view [_ _] (FilteredDB.)))
(def database (DB. 10))
(defn wrong-pred [^OtherDB other ^Datom datom]
  (> (.-value datom) (.-threshold other)))
(-filter-view database wrong-pred)
|}
  in
  match Lg.Compiler.compile_string source with
  | Ok _ -> failwith "distinct nominal callback parameters must be rejected"
  | Error _ -> ()

