let test_recursive_declared_nullable_sequence_supports_not_empty () =
  let source =
    {|
(type-variant parser-node
  MissingNode
  (ValueNode :int)
  (GroupNode :vector<parser-node>))

(declare parse-node parse-nodes)

(defn parse-seq [parse-element forms]
  (when (sequential? forms)
    (reduce
      (fn [parsed form]
        (if-let [parsed-form (parse-element form)]
          (conj parsed parsed-form)
          (reduced nil)))
      [] forms)))

(defn parse-group [forms]
  (let [parsed (parse-nodes forms)]
    (if (not-empty parsed)
      (count parsed)
      0)))

(defn parse-node [form]
  (match form
    MissingNode nil
    (ValueNode value) value
    (GroupNode forms) (parse-group forms)))

(defn parse-nodes [forms]
  (parse-seq parse-node forms))

|}
  in
  let consumer =
    {|
(println
  (str (parse-group [(ValueNode 1) (ValueNode 2)]) ":"
       (parse-group []) ":"
       (parse-group [MissingNode]) ":"
       (parse-group [(GroupNode [(ValueNode 1) (ValueNode 2)])])))
|}
  in
  let compile target =
    compile_chunks_with_stdlib target
      [ ("test/parser.cljc", source); ("test/consumer.cljc", consumer) ]
  in
  let native_source =
    compile Lg.Target.Native
  in
  if string_contains_substring native_source "Runtime_dynamic" then
    failwith "recursive parser sequences must remain statically typed";
  assert_ocaml_runs "recursive_declared_nullable_sequence_supports_not_empty"
    "2:0:0:1\n" native_source;
  ignore (compile Lg.Target.Melange)

let test_nested_keyword_lookup_preserves_nullable_map_evidence () =
  let source =
    {|
(type-record return-map
  (type :keyword)
  (symbols :vector<keyword>))
(type-record query
  (qreturn-map :option<return-map>))

(defn validate-return-map [query]
  (when-some [return-map (:qreturn-map query)]
    (:type return-map))
  (when-some [return-symbols (:symbols (:qreturn-map query))]
    (Rrbvec.length return-symbols))
  true)

(defn validate-return-map-reversed [query]
  (when-some [return-symbols (:symbols (:qreturn-map query))]
    (Rrbvec.length return-symbols))
  (when-some [return-map (:qreturn-map query)]
    (:type return-map))
  true)

(println
  (str (validate-return-map
         (record query (qreturn-map None))) ":"
       (validate-return-map
         (record query
           (qreturn-map
             (Some (record return-map
                     (type :keys)
                     (symbols [:name])))))) ":"
       (validate-return-map-reversed
         (record query (qreturn-map None))) ":"
       (validate-return-map-reversed
         (record query
           (qreturn-map
             (Some (record return-map
                     (type :keys)
                     (symbols [:name]))))))))
|}
  in
  let native_source =
    compile_string_with_stdlib ~target:Lg.Target.Native source |> expect_ok
  in
  if string_contains_substring native_source "Runtime_dynamic" then
    failwith "nested nullable record lookup must remain statically typed";
  assert_ocaml_runs "nested_keyword_lookup_preserves_nullable_map_evidence"
    "true:true:true:true\n" native_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok)

