let test_higher_order_protocol_traversal_requires_closed_sum () =
  let source =
    {|
(defprotocol ITraversable
  (-postwalk [_ f]))

(defn postwalk [form f]
  (if (satisfies? ITraversable form)
    (f (-postwalk form f))
    (f form)))

(defrecord Placeholder []
  ITraversable
  (-postwalk [_ _f]
    (Placeholder.)))

(defrecord Variable [symbol]
  ITraversable
  (-postwalk [_ f]
    (Variable. (postwalk symbol f))))

(defn parse-placeholder [form]
  (when (= '_ form)
    (Placeholder.)))

(defn parse-variable [form]
  (when (symbol? form)
    (Variable. form)))

|}
  in
  Lg.Compiler.compile_string ~target:Lg.Target.Native source
  |> expect_error_contains
       "higher-order protocol traversal requires a closed sum type"

let test_parser_alternatives_use_closed_input_and_result_types () =
  let source =
    {|
(type-variant parse-input
  (InputSymbol :symbol)
  (InputInt :int))

(type-variant pattern-element
  PlaceholderElement
  (VariableElement :symbol)
  (ConstantSymbolElement :symbol)
  (ConstantIntElement :int))

(defn parse-placeholder [form]
  (match form
    (InputSymbol symbol)
      (when (= '_ symbol)
        PlaceholderElement)
    (InputInt _) nil))

(defn parse-variable [form]
  (match form
    (InputSymbol symbol)
      (when (= (first (name symbol)) \?)
        (VariableElement symbol))
    (InputInt _) nil))

(defn parse-constant [form]
  (match form
    (InputSymbol symbol)
      (when-not (= (first (name symbol)) \?)
        (ConstantSymbolElement symbol))
    (InputInt value)
      (ConstantIntElement value)))

(defn parse-pattern-element [form]
  (or (parse-placeholder form)
      (parse-variable form)
      (parse-constant form)))

(println
  (str (some? (parse-pattern-element (InputSymbol '_))) ":"
       (some? (parse-pattern-element (InputSymbol '?name))) ":"
       (some? (parse-pattern-element (InputInt 42)))))
|}
  in
  let native_source =
    compile_string_with_stdlib ~target:Lg.Target.Native source |> expect_ok
  in
  assert_ocaml_runs "parser_alternatives_use_closed_input_and_result_types"
    "true:true:true\n" native_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok)

let test_parser_rule_map_allocates_anonymous_return_record () =
  let source =
    {|
(defrecord PlainSymbol [symbol])
(defrecord RuleVars [required free])
(defrecord RuleForm [^:symbol name vars clauses])

(defn parse-plain-symbol [form]
  (when (symbol? form)
    (PlainSymbol. form)))

(defn parse-rule-vars [forms]
  (RuleVars. [1] [2]))

(defn parse-clauses [_forms]
  [1])

(defn parse-seq [parse-element forms]
  (reduce
    (fn [parsed form]
      (if-let [value (parse-element form)]
        (conj parsed value)
        (reduced nil)))
    []
    forms))

(defn parse-rule [form]
  (let [name (:name form)
        vars (:vars form)
        clauses (:clauses form)
        name* (or (parse-plain-symbol name)
                  (throw (ex-info "missing name" {})))
        vars* (parse-rule-vars vars)
        clauses* (parse-clauses clauses)]
    {:name name*
     :vars vars*
     :clauses clauses*}))

(println
  (:symbol
    (:name
      (parse-rule (RuleForm. 'query ['?x] [1])))))
|}
  in
  let native_source =
    compile_string_with_stdlib ~target:Lg.Target.Native source |> expect_ok
  in
  let anonymous_types = count_generated_anonymous_record_types native_source in
  if anonymous_types <> 1 then
    failwith
      (Printf.sprintf
         "function return maps must allocate one anonymous record type, got %d"
         anonymous_types);
  assert_ocaml_runs
    "parser_rule_map_allocates_anonymous_return_record" "query\n"
    native_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok)

let test_rule_vars_projection_preserves_nominal_argument_type () =
  let source =
    {|
(defrecord RuleVars [^:vector<int> required ^:vector<int> free])
(defrecord RuleBranch [^RuleVars vars ^:vector<int> clauses])
(defrecord ParsedRule
  [^:keyword name ^RuleVars vars ^:vector<int> clauses])

(defn ^ParsedRule parse-rule []
  (ParsedRule. :rule (RuleVars. [1] [2 3]) [1]))

(defn ^RuleBranch parsed-branch [^ParsedRule parsed]
  (RuleBranch. (:vars parsed) (:clauses parsed)))

(defn rule-vars-arity [rule-vars]
  [(count (:required rule-vars)) (count (:free rule-vars))])

(defn validate-arity [^:vector<RuleBranch> branches]
  (let [vars0 (:vars (first branches))
        vars1 (:vars (second branches))
        vars2 (:vars (last branches))
        arity0 (rule-vars-arity vars0)
        _arity1 (rule-vars-arity vars1)
        _arity2 (rule-vars-arity vars2)]
    arity0))

(defn parse-rules []
  (let [branches
        (mapv parsed-branch
          [(parse-rule) (parse-rule) (parse-rule)])]
    (validate-arity branches)))

(println
  (first (parse-rules)))
|}
  in
  let native_source =
    compile_string_with_stdlib ~target:Lg.Target.Native source |> expect_ok
  in
  assert_ocaml_runs "rule_vars_projection_preserves_nominal_argument_type" "1\n"
    native_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok)

let test_for_let_shadowing_replaces_nominal_collection_type () =
  let source =
    {|
(defrecord RuleVars [^:vector<int> required ^:vector<int> free])
(defrecord RuleBranch [^RuleVars vars ^:vector<int> clauses])
(defrecord PlainSymbol [^:string symbol])
(defrecord Rule [^PlainSymbol name ^:vector<RuleBranch> branches])
(defrecord ParsedRule
  [^PlainSymbol name ^RuleVars vars ^:vector<int> clauses])

(defn ^ParsedRule parse-rule []
  (ParsedRule.
    (PlainSymbol. "rule")
    (RuleVars. [1] [2 3])
    [1]))

(defn ^RuleBranch parsed-branch [^ParsedRule parsed]
  (RuleBranch. (:vars parsed) (:clauses parsed)))

(defn rule-vars-arity [^RuleVars rule-vars]
  [(count (:required rule-vars)) (count (:free rule-vars))])

(defn validate-arity
  [^PlainSymbol name ^:vector<RuleBranch> branches]
  (let [vars0 (:vars (first branches))
        arity0 (rule-vars-arity vars0)]
    (doseq [branch (next branches)
            :let [vars (:vars branch)]]
      (when (not= arity0 (rule-vars-arity vars))
        (println (:symbol name))))))

(defn parse-rules []
  (vec
    (for [[name branches]
          (group-by :name
            [(parse-rule) (parse-rule) (parse-rule)])
          :let [branches
                (mapv parsed-branch branches)]]
      (do
        (validate-arity name branches)
        (Rule. name branches)))))

(println (:symbol (:name (first (parse-rules)))))
|}
  in
  let native_source =
    compile_with_stdlib Lg.Target.Native "test/for_let_shadowing.cljc" source
  in
  assert_ocaml_runs "for_let_shadowing_replaces_nominal_collection_type"
    "rule\n" native_source;
  ignore
    (compile_with_stdlib Lg.Target.Melange "test/for_let_shadowing.cljc"
       source)

