let test_reduce_rejects_heterogeneous_vector_accumulator_slots () =
  let source =
    {|
(defn resolve-value [value]
  (if (= value 1)
    (Some 10)
    None))
(defn split-values [values]
  (reduce
    (fn [acc value]
      (if-some [resolved (resolve-value value)]
        (update acc 1 assoc value resolved)
        (update acc 0 conj value)))
    [[] {}]
    values))
(def mixed (split-values [1 2]))
(def only-insert (split-values [2]))
(def empty-result (split-values []))
(println
  (str (= [2] (nth mixed 0)) ":"
       (= {1 10} (nth mixed 1)) ":"
       (= [2] (nth only-insert 0)) ":"
       (= {} (nth only-insert 1)) ":"
       (= [] (nth empty-result 0)) ":"
       (= {} (nth empty-result 1))))
|}
  in
  compile_string_with_stdlib source
  |> expect_error_contains "heterogeneous vector"

