let test_reduce_branch_merges_with_typed_optional_fallback () =
  let source =
    {|
(type-record resolve-output
  (entity :map<keyword;int>)
  (upserts :option<map<keyword;int>>))
(defn resolve-result [found ^:map<keyword;int> entity]
  (if-some [idents (if found (Some #{:id}) None)]
    (reduce-kv
      (fn [^resolve-output output key value]
        (record resolve-output
          (entity (assoc (:entity output) key value))
          (upserts (:upserts output))))
      (record resolve-output
        (entity {})
        (upserts (Some {})))
      entity)
    (record resolve-output
      (entity entity)
      (upserts None))))
(def resolved (resolve-result true {:a 1}))
(def fallback (resolve-result false {:a 1}))
(def empty-resolved (resolve-result true {}))
(println
  (str (= {:a 1} (:entity resolved)) ":"
       (= (Some {}) (:upserts resolved)) ":"
       (= {:a 1} (:entity fallback)) ":"
       (= None (:upserts fallback)) ":"
       (= {} (:entity empty-resolved)) ":"
       (= (Some {}) (:upserts empty-resolved))))
|}
  in
  let ocaml_source = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs "reduce_branch_merges_with_typed_optional_fallback"
    "true:true:true:true:true:true\n" ocaml_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok)

let test_nested_reducers_preserve_closed_entity_lookups () =
  let source =
    {|
(type-record upsert-entry
  (attribute :keyword)
  (value :string))
(type-record entity-input
  (db-id :option<int>))
(defn entity-id-after-upserts [entity upserts]
  (let [upsert-ids
        (reduce-kv
          (fn [result attribute values-to-entities]
            (reduce-kv
              (fn [result value entity-id]
                (assoc
                  result
                  entity-id
                  (record upsert-entry
                    (attribute attribute)
                    (value value))))
              result
              values-to-entities))
          {}
          upserts)
        upsert-count (count upsert-ids)]
    (if (<= 2 upsert-count)
      nil
      (let [[upsert-id upsert] (first upsert-ids)
            entity-id (:db-id entity)]
        (match entity-id
          (Some _) true
          None false)))))
(def present-result
  (entity-id-after-upserts
    (record entity-input (db-id (Some 7)))
    {:name {"Ada" 1}}))
(def missing-result
  (entity-id-after-upserts
    (record entity-input (db-id None))
    {:name {"Ada" 1}}))
(def empty-result
  (entity-id-after-upserts
    (record entity-input (db-id (Some 9)))
    {}))
(def conflict-result
  (entity-id-after-upserts
    (record entity-input (db-id (Some 9)))
    {:name {"Ada" 1} :email {"ada@example.com" 2}}))
(println
  (str present-result ":" missing-result ":" empty-result ":"
       (nil? conflict-result)))
  |}
  in
  let ocaml_source = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs "nested_reducers_preserve_closed_entity_lookups"
    "true:false:true:true\n" ocaml_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok)

