let test_cross_namespace_named_records_project_to_callback_rows () =
  let nodes_source =
    {|
(ns test.nodes)
(type-record tree [value]
  (children :array<value>))
(type-record storage [value]
  (store :fn<tree<value>;int;int>))
(defn make-tree [values]
  (record tree (children values)))
(defn make-storage [store]
  (record storage (store store)))
(defn node-store [node storage]
  (let [_     (:children node)
        store (:store storage)]
    (store node 0)))
|}
  in
  let set_source =
    {|
(ns test.set
  (:require [test.nodes :as nodes]))
(type-record holder [value]
  (backing :storage<value>))
(def root
  (nodes/make-tree (array 10 20)))
(def backing
  (nodes/make-storage (fn [_ count] count)))
(def container
  (record holder (backing backing)))
(def backing-value
  (:backing container))
(def result
  (nodes/node-store root backing-value))
|}
  in
  let compile target =
    let target_name =
      match target with
      | Lg.Target.Native -> "native"
      | Lg.Target.Melange -> "melange"
      | Lg.Target.Js_of_ocaml -> "js_of_ocaml"
    in
    let expect_target = function
      | Ok value -> value
      | Error (error : Lg.Compiler.compile_error) ->
          failwith (target_name ^ ": " ^ error.message)
    in
    let state, nodes_ocaml =
      Lg.Compiler.compile_chunk ~target (stdlib_state target) nodes_source
      |> expect_target
    in
    let _, set_ocaml =
      Lg.Compiler.compile_chunk ~target state set_source |> expect_target
    in
    nodes_ocaml ^ "\n" ^ set_ocaml
  in
  ignore (compile Lg.Target.Native);
  ignore (compile Lg.Target.Melange)

let test_later_nominal_use_recovers_structurally_inferred_record () =
  let source =
    {|
(type-record storage [value owner]
  (restore :fn<int;option<value>>)
  (accessed :fn<int;unit>)
  (owner :option<owner>))
(defn restore-value [address ^:storage<int;string> storage]
  ((:restore storage) address))
(defn lookup-value [storage address]
  (match storage
    (Some storage-value)
    (do
      ((:accessed storage-value) address)
      (restore-value address storage-value))
    None nil))
(def backing
  (record storage
    (restore (fn [address] (Some (+ address 1))))
    (accessed (fn [_] (Stdlib.ignore 0)))
    (owner (Some "owner"))))
(println
  (match (lookup-value (Some backing) 41)
    (Some value) value
    None 0))
|}
  in
  let ocaml_source = Lg.Compiler.compile_string source |> expect_ok in
  assert_ocaml_runs "later_nominal_use_recovers_structurally_inferred_record"
    "42\n" ocaml_source

