let test_transaction_records_keep_concrete_collection_fields () =
  let source =
    {|
(defrecord DB [max-tx])
(defrecord Datom [value])
(defrecord TxReport
  [^DB db-before
   ^DB db-after
   ^:vector<Datom> tx-data
   ^:vector<Datom> tx-redundant
   ^boolean extra])
(defn maybe-datom [present? value]
  (if present? (Datom. value) nil))
(defn transact-report [report datom]
  (let [before ^DB (:db-before report)
        db (:db-after report)
        value (:value datom)
        report' (update report :tx-data conj datom)]
    report'))
(defn transact-add [report old-datom value]
  (let [db (:db-after report)
        report' (assoc report :extra true)
        new-datom (Datom. value)]
    (cond
      (nil? old-datom)
      (transact-report report' new-datom)

      (= (:value old-datom) value)
      (update report' :tx-redundant conj new-datom)

      :else
      (-> report'
          (transact-report old-datom)
          (transact-report new-datom)))))
(def initial (TxReport. (DB. 1) (DB. 1) [] [] false))
(def inserted (transact-add initial nil 2))
(def redundant (transact-add inserted (maybe-datom true 2) 2))
(def repeated (transact-add redundant (maybe-datom true 2) 2))
(def replaced (transact-add initial (maybe-datom true 1) 2))
(println
  (str (count (:tx-data initial)) ":"
       (count (:tx-data inserted)) ":"
       (count (:tx-data redundant)) ":"
       (count (:tx-redundant redundant)) ":"
       (count (:tx-redundant repeated)) ":"
       (count (:tx-data replaced)) ":"
       (= 2
          (:value
            (get (:tx-redundant repeated) 0 (Datom. -1)))) ":"
       (= 2
          (:value
            (get (:tx-data replaced) 1 (Datom. -1))))))
|}
  in
  let ocaml_source = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs "transaction_records_keep_concrete_collection_fields"
    "0:1:1:1:2:2:true:true\n" ocaml_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok);
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Js_of_ocaml source |> expect_ok)

let test_cross_module_fnil_updates_closed_vector_maps () =
  let util_source =
    {|
(ns test.util)
(def conjv (fnil conj []))
|}
  in
  let db_source =
    {|
(ns test.db
  (:require [test.util :as util]))
(defprotocol IDatom
  (datom-value [this]))
(deftype Datom [value]
  IDatom
  (datom-value [_] value))
(defn datom [value]
  (Datom. value))
(def tx-data-key :tx-data)
(def tx-redundant-key :tx-redundant)
(def empty-datoms (pop [(datom 0)]))
(def initial
  (hash-map tx-data-key empty-datoms
            tx-redundant-key empty-datoms))
(def inserted (update initial :tx-data util/conjv (datom 2)))
(def redundant
  (update inserted :tx-redundant util/conjv (datom 2)))
(def repeated
  (update redundant :tx-redundant util/conjv (datom 2)))
(def replaced
  (-> initial
      (update :tx-data util/conjv (datom 1))
      (update :tx-data util/conjv (datom 2))))
(println
  (str (count (get initial :tx-data empty-datoms)) ":"
       (count (get inserted :tx-data empty-datoms)) ":"
       (count (get redundant :tx-data empty-datoms)) ":"
       (count (get redundant :tx-redundant empty-datoms)) ":"
       (count (get repeated :tx-redundant empty-datoms)) ":"
       (count (get replaced :tx-data empty-datoms)) ":"
       (= 2
          (datom-value
            (get (get repeated :tx-redundant empty-datoms)
                 0
                 (Datom. -1)))) ":"
       (= 2
          (datom-value
            (get (get replaced :tx-data empty-datoms)
                 1
                 (Datom. -1))))))
|}
  in
  let compile target =
    compile_chunks_with_stdlib target
      [ ("test/util.cljc", util_source); ("test/db.cljc", db_source) ]
  in
  let native_source = compile Lg.Target.Native in
  assert_ocaml_runs "cross_module_fnil_updates_closed_vector_maps"
    "0:1:1:1:2:2:true:true\n" native_source;
  ignore (compile Lg.Target.Melange)

