let test_source_juxt_matches_clojurescript_arities () =
  let source =
    {|
(ns app.source-juxt
  (:require [cljs.core :as core :refer [juxt]]))

(def calls (atom 0))
(defn mark [value]
  (swap! calls (fn [state] (+ (* state 100) value))))
(defn left
  ([] (do (mark 10) 10))
  ([x] (do (mark 11) (+ x 10)))
  ([x y] (do (mark 12) (+ x y 10)))
  ([x y z] (do (mark 13) (+ x y z 10)))
  ([x y z & more]
   (do (mark 14) (apply + (+ x y z 10) more))))
(defn right
  ([] (do (mark 20) 20))
  ([x] (do (mark 21) (+ x 20)))
  ([x y] (do (mark 22) (+ x y 20)))
  ([x y z] (do (mark 23) (+ x y z 20)))
  ([x y z & more]
   (do (mark 24) (apply + (+ x y z 20) more))))
(defn middle
  ([] 30)
  ([x] (+ x 30))
  ([x y] (+ x y 30))
  ([x y z] (+ x y z 30))
  ([x y z & more] (apply + (+ x y z 30) more)))
(defn fourth
  ([] 40)
  ([x] (+ x 40))
  ([x y] (+ x y 40))
  ([x y z] (+ x y z 40))
  ([x y z & more] (apply + (+ x y z 40) more)))

(def build (identity juxt))
(def one (build left))
(def two (build left right))
(def three (build left right middle))
(def four (build left right middle fourth))
(def referred (juxt (fn [x] (+ x 1)) (fn [x] (+ x 2))))
(def aliased (core/juxt (fn [x] (+ x 3)) (fn [x] (+ x 4))))
(def qualified
  (clojure.core/juxt (fn [x] (+ x 5)) (fn [x] (+ x 6))))
(def direct-calls (atom 0))
(defn direct-mark [value]
  (swap! direct-calls (fn [state] (+ (* state 10) value))))
(def direct-order
  (juxt (fn [x] (do (direct-mark 1) (+ x 1)))
        (fn [x] (do (direct-mark 2) (+ x 2)))))

(println (= [10] (one)))
(println (= [11 21] (two 1)))
(println (= [13 23 33] (three 1 2)))
(println (= [16 26 36 46] (four 1 2 3)))
(println (= [20 30 40 50] (apply four [1 2 3 4])))
(println (= 101121122213231424 @calls))
(println (= [2 3] (referred 1)))
(println (= [4 5] (aliased 1)))
(println (= [6 7] (qualified 1)))
(println (= [2 3] (direct-order 1)))
(println (= 12 @direct-calls))
|}
  in
  let expected = String.concat "" (List.init 11 (fun _ -> "true\n")) in
  let native_source =
    compile_with_stdlib Lg.Target.Native "test/source_juxt.cljc" source
  in
  let consumer_source = compile_string_from_stdlib source |> expect_ok in
  if string_contains_substring consumer_source "Runtime_dynamic" then
    failwith "source juxt must preserve static overloaded function values";
  assert_ocaml_runs "source_juxt_matches_clojurescript_arities" expected
    native_source;
  ignore
    (compile_with_stdlib Lg.Target.Melange "test/source_juxt.cljc" source)

let test_source_comp_matches_clojurescript_arities () =
  let source =
    {|
(ns app.source-comp
  (:require [cljs.core :as core :refer [comp]]))

(def calls (atom 0))
(defn mark [value]
  (swap! calls (fn [state] (+ (* state 10) value))))
(defn total
  ([] (do (mark 1) 1))
  ([x] (do (mark 1) x))
  ([x y] (do (mark 1) (+ x y)))
  ([x y z] (do (mark 1) (+ x y z)))
  ([x y z & more] (do (mark 1) (apply + (+ x y z) more))))
(defn add-ten [value]
  (do (mark 2) (+ value 10)))
(defn double-value [value]
  (do (mark 3) (* value 2)))

(def identity-composition ((identity comp)))
(def one ((identity comp) total))
(def two ((identity comp) add-ten total))
(def three ((identity comp) double-value add-ten total))

(println (= 7 (identity-composition 7)))
(println (= 1 (one)))
(println (= 3 (one 1 2)))
(println (= 16 (two 1 2 3)))
(println (= 40 (apply three [1 2 3 4])))
(println (= 1112123 @calls))

(def referred
  (comp (fn [value] (+ value 1))
        (fn [value] (* value 2))
        (fn [value] (+ value 3))
        (fn [value] (- value 4))))
(def aliased
  (core/comp (fn [value] (+ value 1))
             (fn [value] (* value 2))))
(def qualified
  (clojure.core/comp (fn [value] (+ value 1))
                     (fn [value] (* value 3))))
(def empty-qualified (clojure.core/comp))

(println (= 7 (referred 4)))
(println (= 9 (aliased 4)))
(println (= 13 (qualified 4)))
(println (= 9 (empty-qualified 9)))
|}
  in
  let expected = String.concat "" (List.init 10 (fun _ -> "true\n")) in
  let native_source =
    compile_with_stdlib Lg.Target.Native "test/source_comp.cljc" source
  in
  let consumer_source = compile_string_from_stdlib source |> expect_ok in
  if string_contains_substring consumer_source "Runtime_dynamic" then
    failwith "source comp must preserve static overloaded function values";
  assert_ocaml_runs "source_comp_matches_clojurescript_arities" expected
    native_source;
  ignore
    (compile_with_stdlib Lg.Target.Melange "test/source_comp.cljc" source)

let test_source_fnil_and_partial_match_clojurescript_arities () =
  let source =
    {|
(ns app.source-fnil-partial
  (:require [cljs.core :as core :refer [fnil partial]]))

(defn append-digit [state digit]
  (+ (* state 10) digit))
(defn digits
  ([a] a)
  ([a b] (append-digit a b))
  ([a b c] (append-digit (append-digit a b) c))
  ([a b c & more]
   (reduce append-digit (append-digit (append-digit a b) c) more)))

(def partial-identity ((identity partial) digits))
(def partial-one ((identity partial) digits 1))
(def partial-two ((identity partial) digits 1 2))
(def partial-three ((identity partial) digits 1 2 3))
(def partial-many ((identity partial) digits 1 2 3 4))

(println (= 123 (partial-identity 1 2 3)))
(println (= 1 (partial-one)))
(println (= 12 (partial-one 2)))
(println (= 123 (partial-one 2 3)))
(println (= 1234 (partial-one 2 3 4)))
(println (= 12345 (apply partial-one [2 3 4 5])))
(println (= 12 (partial-two)))
(println (= 123 (partial-two 3)))
(println (= 1234 (partial-three 4)))
(println (= 1234 (partial-many)))
(println (= 123456 (partial-many 5 6)))

(def fnil-one ((identity fnil) digits 9))
(def fnil-two ((identity fnil) digits 8 7))
(def fnil-three ((identity fnil) digits 8 7 6))

(println (= 9 (fnil-one nil)))
(println (= 92 (fnil-one nil 2)))
(println (= 9234 (fnil-one nil 2 3 4)))
(println (= 87 (fnil-two nil nil)))
(println (= 173 (fnil-two 1 nil 3)))
(println (= 87 (fnil-three nil nil)))
(println (= 876 (fnil-three nil nil nil)))
(println (= 1764 (fnil-three 1 nil nil 4)))

(def partial-evaluations (atom 0))
(defn add-fixed [left right] (+ left right))
(def partial-once
  (partial add-fixed (swap! partial-evaluations inc)))
(println (and (= 3 (partial-once 2))
              (= 3 (partial-once 2))
              (= 1 @partial-evaluations)))
(def fnil-evaluations (atom 0))
(def fnil-once
  (fnil (fn [value] value) (swap! fnil-evaluations inc)))
(println (and (= 1 (fnil-once nil))
              (= 1 (fnil-once nil))
              (= 1 @fnil-evaluations)))

(def referred-partial
  (partial (fn [left right] (+ left right)) 10))
(def aliased-partial
  (core/partial (fn [left right] (* left right)) 3))
(def qualified-partial
  (clojure.core/partial (fn [left right] (- left right)) 9))
(def referred-fnil
  (fnil (fn [value] (+ value 1)) 4))
(def aliased-fnil
  (core/fnil (fn [value] (* value 2)) 5))
(def qualified-fnil
  (clojure.core/fnil (fn [value] (- value 1)) 7))
(def overloaded-fnil (fnil + 10))

(println (= 15 (referred-partial 5)))
(println (= 12 (aliased-partial 4)))
(println (= 7 (qualified-partial 2)))
(println (= 5 (referred-fnil nil)))
(println (= 10 (aliased-fnil nil)))
(println (= 6 (qualified-fnil nil)))
(println (= 15 (overloaded-fnil nil 5)))
(println (= 3 (get (update (hash-map :count 1)
                           :count
                           (fnil + 0)
                           2)
                    :count)))
|}
  in
  let expected = String.concat "" (List.init 29 (fun _ -> "true\n")) in
  let native_source =
    compile_with_stdlib Lg.Target.Native "test/source_fnil_partial.cljc" source
  in
  let consumer_source = compile_string_from_stdlib source |> expect_ok in
  if string_contains_substring consumer_source "Runtime_dynamic" then
    failwith "source fnil and partial must preserve static function values";
  assert_ocaml_runs "source_fnil_partial_matches_clojurescript_arities" expected
    native_source;
  ignore
    (compile_with_stdlib Lg.Target.Melange "test/source_fnil_partial.cljc"
       source)

