let test_module_functor_application_is_checked_by_ocaml () =
  Lg.Compiler.compile_string
    {|
(module-signature MathSig
  (val answer :int))
(module Bad
  (def answer "forty"))
(module-functor Make [M MathSig]
  (def result M/answer))
(module-apply App Make Bad)
